__NUXT_JSONP__("/finanzas-publicas/columnas", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o){return {data:[{columnas:[{slug:"la_paradoja_del_empleo_mas_ingresos_mas_informalidad",title:"La paradoja del empleo: más ingresos, más informalidad ",date:"2026-06-12T16:29:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002Fe3bae621-3bdf-4fa7-bcdf-10ba8e9c5fab\u002F","img-alt":"Empleo informal",autor:h,medio:e,link:"https:\u002F\u002Fwww.eleconomista.com.mx\u002Fopinion\u002Fparadoja-empleo-ingresos-informalidad-20260610-817726.html",category:a,extracto:"Las desventajas de la informalidad frente a la formalidad son sustanciales en términos de niveles salariales, productividad, acceso a la salud y contribución a la recaudación fiscal, entre otras.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fla_paradoja_del_empleo_mas_ingresos_mas_informalidad",extension:c,createdAt:i,updatedAt:i},{slug:"cuenta_publica_2025_del_paquete_economico_a_la_realidad",title:"Cuenta Pública 2025: del Paquete Económico a la realidad",date:"2026-05-14T15:48:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002Ff3db9a8f-177b-4ab7-8071-12e89b593af3\u002F-\u002Fcrop\u002F2649x1536\u002F0,0\u002F-\u002Fpreview\u002F","img-alt":"Cuenta pública 2025",autor:f,medio:g,link:"https:\u002F\u002Fgrupoanimal.mx\u002Fopinion\u002Fcuenta-publica-2025-del-paquete-economico-a-la-realidad",category:a,extracto:"México enfrenta hoy una presión creciente sobre sus finanzas públicas. El envejecimiento de la población, las necesidades de salud y educación y la expansión de programas sociales requieren cada vez más recursos. Pero al mismo tiempo, el país sigue teniendo una baja capacidad recaudatoria y depende, en parte, del endeudamiento para cubrir algunas de sus necesidades.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fcuenta_publica_2025_del_paquete_economico_a_la_realidad",extension:c,createdAt:j,updatedAt:j},{slug:"mas_estudios_misma_brecha_genero_ingresos_y_cuidados",title:"Más estudios, misma brecha: género, ingresos y cuidados",date:"2026-02-24T15:53:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F4656e2cb-06f0-4864-94f2-6c0979d98a69\u002F-\u002Fcrop\u002F1021x846\u002F0,91\u002F-\u002Fpreview\u002F","img-alt":"Movilidad social",autor:f,medio:g,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Fmas-estudios-misma-brecha-genero-ingresos-y-cuidados",category:a,extracto:"Si bien un mayor grado académico es clave para la movilidad social, esta receta no tiene efectos similares en mujeres y hombres. Las mujeres deben sortear antes otras barreras, como la estrecha entrada al mercado laboral, relacionada, principalmente, con sus labores de cuidados. En ese sentido, hace falta una política pública que ataque la raíz del problema.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fmas_estudios_misma_brecha_genero_ingresos_y_cuidados",extension:c,createdAt:k,updatedAt:k},{slug:"mas_horas_menos_pib_el_sello_de_la_productividad_mexicana",title:"Más horas, menos PIB: el sello de la productividad mexicana",date:"2026-02-10T18:24:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002F537aec2d-3775-4947-88a1-21422afa1078\u002F","img-alt":"Baja productividad",autor:l,medio:e,link:"https:\u002F\u002Fwww.eleconomista.com.mx\u002Fopinion\u002Fhoras-pib-sello-productividad-mexicana-20260210-799186.html",category:a,extracto:"Es indispensable asumir que ni el aumento del salario mínimo ni las transferencias monetarias pueden sustituir, en el largo plazo, todos los beneficios de una economía sana que crece de manera sostenida.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fmas_horas_menos_pib_el_sello_de_la_productividad_mexicana",extension:c,createdAt:"2026-07-19T00:56:17.194Z",updatedAt:"2026-07-19T00:56:17.195Z"},{slug:"un_escenario_incompleto_del_bienestar_la_salud_y_la_educacion_en_el_presupuesto_2026",title:"Un escenario incompleto del bienestar: la salud y la educación en el presupuesto 2026",date:"2025-09-25T20:14:56.678Z",img:"https:\u002F\u002Fucarecdn.com\u002F91bd1518-6bb5-4f13-a05a-a8a61ec04d1d\u002F","img-alt":"Presupuesto salud y educación",autor:f,medio:g,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Fun-escenario-incompleto-del-bienestar-la-salud-y-la-educacion-en-el-presupuesto-2026",category:a,extracto:"El presupuesto para salud en 2026 refuerza la atención para quienes ya están cubiertos, pero deja vulnerable a la población más desprotegida, mientras que en educación la inversión se concentra en transferencias directas a los estudiantes, sin atender la calidad educativa o la infraestructura escolar.",toc:[{id:"salud-crecimiento-o-desequilibrio",depth:d,text:"Salud: ¿crecimiento o desequilibrio?"},{id:"educación-un-embudo-que-deja-a-muchos-fuera",depth:d,text:"Educación: un embudo que deja a muchos fuera"}],dir:b,path:"\u002Fcolumnas\u002Fun_escenario_incompleto_del_bienestar_la_salud_y_la_educacion_en_el_presupuesto_2026",extension:c,createdAt:m,updatedAt:m},{slug:"primero_la_politica_el_pago_de_la_deuda_vendra_despues",title:"Primero la política, el pago de la deuda vendrá después",date:"2025-09-18T16:42:40.019Z",img:"https:\u002F\u002Fucarecdn.com\u002Fd0f221c1-3e5e-478b-8849-f9e3abac4d7d\u002F","img-alt":"Deuda pública",autor:h,medio:e,link:"https:\u002F\u002Fwww.eleconomista.com.mx\u002Fopinion\u002Fprimero-politica-pago-deuda-vendra-20250918-777717.html",category:a,extracto:"Es necesario replantear nuestro gasto para atender adecuadamente las necesidades actuales de la población en materia de salud, educación, seguridad, entre otros ámbitos, por encima del deseo que tiene el gobierno de mantenerse en el poder.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fprimero_la_politica_el_pago_de_la_deuda_vendra_despues",extension:c,createdAt:n,updatedAt:n},{slug:"radiografia_de_las_donaciones_en_mexico",title:"Radiografía de las donaciones en México",date:"2025-08-27T17:32:43.454Z",img:"https:\u002F\u002Fucarecdn.com\u002F91b847e0-cc0e-402c-b694-1cf05211d619\u002F",autor:l,medio:e,link:"https:\u002F\u002Fwww.eleconomista.com.mx\u002Fopinion\u002Fradiografia-donaciones-mexico-20250827-774501.html?fbclid=IwY2xjawMit_tleHRuA2FlbQIxMABicmlkETE3VGdkRm80Q2lEcVlGMWE3AR5vjzDGaa6eoPagMSe4l8eFLqTIQpNBSWLzzu7BBj8AqwW2P1fB3MY9zkVL-g_aem_j2IC7UQhE8K2JCGNAzMt0g",category:a,extracto:"El donativo en México se concentra en instituciones asistenciales, mientras que el apoyo a investigación científica o tecnológica disminuye. Esto refleja un interés en atender necesidades inmediatas más que en solucionar problemas estructurales de manera sostenible.",toc:[],dir:b,path:"\u002Fcolumnas\u002Fradiografia_de_las_donaciones_en_mexico",extension:c,createdAt:"2025-11-25T01:24:03.246Z",updatedAt:"2025-11-25T01:24:03.247Z"},{slug:"el_costo_de_la_austeridad_recortes_que_afectan_el_bienestar",title:"El costo de la austeridad: recortes que afectan el bienestar",date:"2025-08-12T21:27:22.487Z",img:"https:\u002F\u002Fucarecdn.com\u002F76e1c68a-014b-4426-8dce-4b86c31cbb61\u002F",autor:f,medio:g,link:"https:\u002F\u002Fanimalpolitico.com\u002Fanalisis\u002Finvitades\u002Fcosto-austeridad-recortes-bienestar",category:a,extracto:"Un programa de educación que no gasta a tiempo sus recursos no puede construir escuelas ni equiparlas. Un programa de salud que no ejerce su presupuesto no puede brindar atención ni comprar medicinas o equipo médico. El retraso y recorte en el gasto es un obstáculo real que impide que los objetivos de desarrollo y bienestar se cumplan.",toc:[{id:"menor-gasto-en-áreas-clave",depth:d,text:"Menor gasto en áreas clave"},{id:"los-más-vulnerables-los-más-afectados",depth:d,text:"Los más vulnerables, los más afectados"},{id:"anticorrupción-y-medio-ambiente-en-pausa",depth:d,text:"Anticorrupción y medio ambiente, en pausa"},{id:"la-urgencia-de-gastar-bien",depth:d,text:"La urgencia de gastar bien"}],dir:b,path:"\u002Fcolumnas\u002Fel_costo_de_la_austeridad_recortes_que_afectan_el_bienestar",extension:c,createdAt:o,updatedAt:o}],total:[{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{},{}]}],fetch:{},mutations:[]}}("finanzas-publicas","\u002Fcolumnas",".md",3,"El Economista","Mireya Mondragón","Animal Político","Liliana Alvarado ","2026-07-19T00:56:17.189Z","2026-07-19T00:56:17.181Z","2026-07-19T00:56:17.193Z","Liliana Alvarado","2025-11-25T01:24:03.250Z","2025-11-25T01:24:03.245Z","2025-11-25T01:24:03.236Z")));